double findMedianSortedArrays(vector<int>& a, vector<int>& b) {
    if (a.size() > b.size()) swap(a, b);
    int m = a.size(), n = b.size(), lo = 0, hi = m, half = (m + n + 1) / 2;
    while (lo <= hi) {
        int i = (lo + hi) / 2, j = half - i;
        double al = i > 0 ? a[i - 1] : -1e18, ar = i < m ? a[i] : 1e18, bl = j > 0 ? b[j - 1] : -1e18, br = j < n ? b[j] : 1e18;
        if (al <= br && bl <= ar) return (m + n) % 2 ? max(al, bl) : (max(al, bl) + min(ar, br)) / 2;
        if (al > br) hi = i - 1; else lo = i + 1;
    }
    return 0;
}
